import Joi from "joi";

const digitsOnlyNumber = Joi.alternatives().try(
  Joi.number().integer().min(0).strict(),
  Joi.string().pattern(/^\d+$/)
).custom((value) => Number(value));

export const createVendorSchema = Joi.object({
  name: Joi.string().required(),
  category: Joi.string().allow("", null),
  phone: Joi.string().required(),
  email: Joi.string().email().allow("", null),
  address: Joi.string().allow("", null),
  initialInvestment: digitsOnlyNumber.default(0),
  openingBalance: Joi.number().default(0),
  status: Joi.string().valid("active", "inactive").default("active"),
  notes: Joi.string().allow("", null),
  productCosts: Joi.array().items(
    Joi.object({
      _id: Joi.any().optional(),
      productId: Joi.string().allow(null, ""),
      isCustom: Joi.boolean().default(false),
      customName: Joi.string().allow("", null),
      powderCostPerGram: Joi.number().default(0),
      powderGrams: Joi.number().default(0),
      packagingCost: Joi.number().default(0),
      packagingGrams: Joi.number().default(0),
      sideLabelCost: Joi.number().default(0),
      sideLabelGrams: Joi.number().default(0),
      upperLabelCost: Joi.number().default(0),
      upperLabelGrams: Joi.number().default(0),
      spoonCost: Joi.number().default(0),
      spoonGrams: Joi.number().default(0),
      shippingCharges: Joi.number().default(0),
      shippingGrams: Joi.number().default(0),
      jarCost: Joi.number().default(0),
      jarGrams: Joi.number().default(0),
      plasticSleevesCost: Joi.number().default(0),
      plasticSleevesGrams: Joi.number().default(0),
      courierBagCost: Joi.number().default(0),
      courierBagGrams: Joi.number().default(0),
      tapeCost: Joi.number().default(0),
      tapeGrams: Joi.number().default(0),
      bubbleSheetCost: Joi.number().default(0),
      bubbleSheetGrams: Joi.number().default(0),
      extraCosts: Joi.array().items(
        Joi.object({
          label: Joi.string().allow("", null),
          amount: Joi.number().default(0),
          grams: Joi.number().default(0),
          unit: Joi.string().allow("g", "kg", "units").default("g"),
        }).unknown(true)
      ),
      finalCost: Joi.number().allow(null).default(null),
      powderUnit: Joi.string().allow("g", "kg", "units").default("g"),
      jarUnit: Joi.string().allow("g", "kg", "units").default("units"),
      packagingUnit: Joi.string().allow("g", "kg", "units").default("units"),
      sideLabelUnit: Joi.string().allow("g", "kg", "units").default("units"),
      upperLabelUnit: Joi.string().allow("g", "kg", "units").default("units"),
      spoonUnit: Joi.string().allow("g", "kg", "units").default("units"),
      shippingUnit: Joi.string().allow("g", "kg", "units").default("units"),
      plasticSleevesUnit: Joi.string().allow("g", "kg", "units").default("units"),
      courierBagUnit: Joi.string().allow("g", "kg", "units").default("units"),
      tapeUnit: Joi.string().allow("g", "kg", "units").default("units"),
      bubbleSheetUnit: Joi.string().allow("g", "kg", "units").default("units"),
    }).unknown(true)
  ).optional(),
});

