      upperLabelCost: Joi.number().optional(),
      upperLabelGrams: Joi.number().optional(),
      spoonCost: Joi.number().optional(),
      spoonGrams: Joi.number().optional(),
      shippingCharges: Joi.number().optional(),
      shippingGrams: Joi.number().optional(),
      jarCost: Joi.number().optional(),
      jarGrams: Joi.number().optional(),
      plasticSleevesCost: Joi.number().optional(),
      plasticSleevesGrams: Joi.number().optional(),
      courierBagCost: Joi.number().optional(),
      courierBagGrams: Joi.number().optional(),
      tapeCost: Joi.number().optional(),
      tapeGrams: Joi.number().optional(),
      bubbleSheetCost: Joi.number().optional(),
